    if(corpus.some(d=>!contract.configurations.includes(d.id)) || contract.configurations.some(id=>!Object.hasOwn(reference,id)))throw new Error('Frozen configuration coverage mismatch');
    let checks=0,passed=0;const failed=[],maxima={},refusals=[],identities=[];
